import * as T from 'three';
import {ALIGNMENTS} from './alignmentData';

/**
 * Plan alignment of a course as data: a start pose at the winning post and a chain of elements
 * ('L' line, 'S' clothoid easing the curvature to `kEnd`, 'A' circular arc). Curvature is
 * continuous along the whole chain, the lengths add up to the official lap, and every course
 * of a venue is built from the same shared elements wherever its rails coincide.
 * Generated by scripts/fit_alignment.mjs from the digitized plans and the official figures.
 */
export type AlignmentElement = ['L' | 'S' | 'A', number, number?];
export type VenueAlignment = {
  /** Metres per plan pixel (the plan is only a shape reference; the official lap fixes the size). */
  scale: number;
  /** Winning post, relative to the plan centre, in metres; heading is atan2(z, x). */
  pose: {x: number; z: number; h: number};
  /** Courses whose winning post is not at `pose` (Tokyo's dirt lies inside the turf). */
  poses?: Record<string, {x: number; z: number; h: number}>;
  courses: Record<string, AlignmentElement[]>;
};

/** Start pose of a course: its own if it has one, else the venue's. */
export const poseFor = (alignment: VenueAlignment, course: string) => alignment.poses?.[course] ?? alignment.pose;

export const alignmentFor = (venueCode: string): VenueAlignment | undefined => ALIGNMENTS[venueCode];

/** Walks the chain from `pose`, calling `emit` with x, z, heading and distance after every step. */
export function walkAlignment(
  pose: {x: number; z: number; h: number},
  elements: AlignmentElement[],
  step: number,
  emit?: (x: number, z: number, h: number, s: number) => void,
) {
  let {x, z, h} = pose;
  let k = 0;
  let s = 0;
  for (const [kind, length, kEnd = 0] of elements) {
    const k0 = kind === 'L' ? 0 : k;
    const k1 = kind === 'L' ? 0 : kind === 'A' ? k : kEnd;
    const n = Math.max(1, Math.ceil(length / step));
    const ds = length / n;
    for (let i = 0; i < n; i++) {
      const km = k0 + (k1 - k0) * ((i + 0.5) / n);
      const hm = h + (km * ds) / 2;
      x += Math.cos(hm) * ds;
      z += Math.sin(hm) * ds;
      h += km * ds;
      s += ds;
      emit?.(x, z, h, s);
    }
    k = k1;
  }
  return {x, z, h, length: s};
}

/** The rail as a closed curve through points about 2 m apart. */
export function alignmentCurve(alignment: VenueAlignment, course: string) {
  const elements = alignment.courses[course] ?? alignment.courses.turf;
  const pose = poseFor(alignment, alignment.courses[course] ? course : 'turf');
  const points = [new T.Vector3(pose.x, 0, pose.z)];
  // Very short elements would put points almost on top of each other; the spline needs even spacing.
  walkAlignment(pose, elements, 2, (x, z) => {
    const last = points[points.length - 1];
    if (Math.hypot(x - last.x, z - last.z) >= 1) points.push(new T.Vector3(x, 0, z));
  });
  // The chain closes on its first point: drop what lands within a metre of it.
  while (points.length > 1 && Math.hypot(points[points.length - 1].x - points[0].x, points[points.length - 1].z - points[0].z) < 1) points.pop();
  const curve = new T.CatmullRomCurve3(points, true, 'centripetal');
  curve.arcLengthDivisions = 4096;
  return curve;
}

/**
 * Corner positions (metres from the winning post along the race direction): where the turn
 * accumulated since the post reaches 1/8, 3/8, 5/8 and 7/8 of the lap's total turn.
 */
export function alignmentCorners(alignment: VenueAlignment, course: string, lap: number) {
  const elements = alignment.courses[course] ?? alignment.courses.turf;
  const total = elements.reduce((sum, [, length]) => sum + length, 0);
  const marks: {s: number; turn: number}[] = [{s: 0, turn: 0}];
  let k = 0;
  let turn = 0;
  let s = 0;
  for (const [kind, length, kEnd = 0] of elements) {
    const k0 = kind === 'L' ? 0 : k;
    const k1 = kind === 'L' ? 0 : kind === 'A' ? k : kEnd;
    turn += ((k0 + k1) / 2) * length;
    s += length;
    marks.push({s, turn});
    k = k1;
  }
  const full = turn;
  return [1, 3, 5, 7].map((i) => {
    const target = (full * i) / 8;
    let j = 1;
    while (j < marks.length && Math.abs(marks[j].turn) < Math.abs(target)) j++;
    // Inside an element the turn is quadratic in distance (linear for lines and arcs); a fine
    // interpolation is enough.
    const a = marks[j - 1], b = marks[j];
    const t = (target - a.turn) / (b.turn - a.turn || 1);
    return (a.s + (b.s - a.s) * Math.max(0, Math.min(1, t))) * (lap / total);
  });
}
